          <tr>
            <th scope="row">Redacción de artículos de blog</th>
            <td><span class="rm-pricing-pe__no" aria-hidden="true">—</span><span class="rm-pricing-pe__sr-only">No incluido</span></td>
            <td class="rm-pricing-pe__col--highlight"><span class="rm-pricing-pe__no" aria-hidden="true">—</span><span class="rm-pricing-pe__sr-only">No incluido</span></td>
            <td><span class="rm-pricing-pe__yes" aria-hidden="true">✓</span><span class="rm-pricing-pe__sr-only">Incluido</span></td>
          </tr>
          <tr>
            <th scope="row">Revisión mensual del calendario</th>
            <td><span class="rm-pricing-pe__no" aria-hidden="true">—</span><span class="rm-pricing-pe__sr-only">No incluido</span></td>
            <td class="rm-pricing-pe__col--highlight"><span class="rm-pricing-pe__no" aria-hidden="true">—</span><span class="rm-pricing-pe__sr-only">No incluido</span></td>
            <td><span class="rm-pricing-pe__yes" aria-hidden="true">✓</span><span class="rm-pricing-pe__sr-only">Incluido</span></td>
          </tr>
          <tr class="rm-pricing-pe__price-row">
            <th scope="row">Precio</th>
